def _read():
    data={}
    for line in ROWS.splitlines():
        fields=line.split("|")
        if len(fields)!=len(KEYS)+1:
            raise ValueError("Incomplete Granite AFT translation: "+fields[0])
        code,*values=fields
        if code in data or not all(v.strip() for v in values):
            raise ValueError("Duplicate or empty Granite AFT translation: "+code)
        data[code]=dict(zip(KEYS,values))
    if set(data)!=set(LOCALES) or len(data)!=36:
        raise ValueError("Granite AFT translations differ from exactly 36 app locales: "+
                         str(sorted(set(data)^set(LOCALES))))
    return data

COPY=_read()

def copy(code):
    return COPY.get(code,COPY["en-US"])
